struct Edge {
    int u;
    int v;
    int c;
    int r;

    Edge(int uu, int vv, int cc, int rr)
        : u(uu), v(vv), c(cc), r(rr) {}
};

vector<Edge> E;
vector<vector<int> > ady;

int maxflow(int source, int sink) {
    for (int f = 0;;) {
        vector<int> prev(ady.size(), -1);
        queue<int> Q;
        Q.push(source);
        prev[source] = -2;

        while (!Q.empty()) {
            int u = Q.front();
            Q.pop();

            for (int i = 0; i < static_cast<int>(ady[u].size()); ++i) {
                int e = ady[u][i];
                int v = E[e].v;

                if (E[e].c == 0 || prev[v] != -1)
                    continue;

                Q.push(v);
                prev[v] = e;
            }
        }

        if (prev[sink] < 0)
            return f;

        int c = 0x7fffffff;

        for (int x = sink; x != source; x = E[prev[x]].u)
            c = min(c, E[prev[x]].c);

        for (int x = sink; x != source; x = E[prev[x]].u) {
            E[prev[x]].c -= c;
            E[E[prev[x]].r].c += c;
        }

        f += c;
    }
}

void add(int u, int v, int c, bool dirigido = true) {
    Edge e1(u, v, c, static_cast<int>(E.size()) + 1);
    ady[u].push_back(static_cast<int>(E.size()));
    E.push_back(e1);

    Edge e2(v, u, dirigido ? 0 : c, static_cast<int>(E.size()) - 1);
    ady[v].push_back(static_cast<int>(E.size()));
    E.push_back(e2);
}

